<script setup lang="ts">
import type { Project, ValueRef } from '../lib/model'
import { dataPoints } from '../lib/resources'
const props = defineProps<{ modelValue: ValueRef; project: Project; literalType?: string }>()
const emit = defineEmits<{ 'update:modelValue': [value: ValueRef] }>()
function changeSource(event: Event) { const source = (event.target as HTMLSelectElement).value as ValueRef['source']; emit('update:modelValue', source === 'literal' ? { source, value: '' } : source === 'message' ? { source, path: 'payload' } : { source, key: '' }) }
function literal(value: string) { let parsed: unknown = value; try { parsed = JSON.parse(value) } catch { /* A plain string is a valid literal. */ } emit('update:modelValue', { source: 'literal', value: parsed }) }
</script>

<template><div class="value-editor"><select :value="modelValue.source" aria-label="值来源" @change="changeSource"><option value="literal">常量</option><option value="message">消息字段</option><option value="variable">项目变量</option><option value="input">控件输入</option><option value="point">设备数据点</option></select><input v-if="modelValue.source === 'literal'" :value="typeof modelValue.value === 'object' ? JSON.stringify(modelValue.value) : String(modelValue.value ?? '')" placeholder="输入值或 JSON" @change="literal(($event.target as HTMLInputElement).value)" /><input v-else-if="modelValue.source === 'message'" :value="modelValue.path" placeholder="payload.temperature" @change="emit('update:modelValue', { source: 'message', path: ($event.target as HTMLInputElement).value })" /><select v-else-if="modelValue.source === 'variable'" :value="modelValue.key" @change="emit('update:modelValue', { source: 'variable', key: ($event.target as HTMLSelectElement).value })"><option value="">选择变量</option><option v-for="variable in project.variables" :key="variable.id" :value="variable.id">{{ variable.name }}</option></select><select v-else-if="modelValue.source === 'input'" :value="modelValue.key" @change="emit('update:modelValue', { source: 'input', key: ($event.target as HTMLSelectElement).value })"><option value="">选择输入控件</option><template v-for="page in project.pages" :key="page.id"><option v-for="widget in page.widgets.filter(w => ['input','switch','select'].includes(w.kind))" :key="widget.id" :value="widget.id">{{ page.name }} / {{ widget.name }}</option></template></select><template v-else><input :value="modelValue.key" list="hmi-data-point-options" placeholder="sensor.temperature" @change="emit('update:modelValue', { source: 'point', key: ($event.target as HTMLInputElement).value })" /><datalist id="hmi-data-point-options"><option v-for="point in dataPoints(project)" :key="point.key" :value="point.key">{{ point.label }}</option></datalist></template></div></template>
